def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_d = 0
    my_d = 0
    for a, b in history:
        if a == 'D':
            my_d += 1
        if b == 'D':
            opp_d += 1

    if n == 98:
        if opp_d == 0 and my_d > 0:
            return 'D'
        return 'C'

    last_my, last_opp = history[-1]

    if opp_d * 2 > n:
        return 'D'

    if last_opp == 'D':
        if last_my == 'C':
            if n >= 2 and history[-2][0] == 'D':
                return 'C'
            if n >= 3 and history[-3][0] == 'D':
                return 'C'
            return 'D'
        else:
            if n >= 2 and history[-2][0] == 'C' and history[-2][1] == 'C':
                return 'C'
            if opp_d * 2 > n:
                return 'D'
            return 'C'
    else:
        if last_my == 'D':
            return 'C'
        else:
            successes = 0
            failures = 0
            start = max(1, n - 20)
            for i in range(start, n):
                if history[i-1][0] == 'C' and history[i-1][1] == 'C' and history[i][0] == 'D':
                    if history[i][1] == 'C':
                        if i + 1 < n and history[i+1][1] == 'D':
                            failures += 1
                        else:
                            successes += 1
                    else:
                        failures += 1
            total = successes + failures
            if total == 0:
                p = 0.1
            else:
                p = 0.2 + 0.6 * (successes / total)
                if failures > 0:
                    p *= 0.5
            if p > 0.9:
                p = 0.9
            if p < 0.02:
                p = 0.02
            if rng.random() < p:
                return 'D'
            return 'C'
